  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter-card h2 {
  font-family: var(--font-display);
  font-size: clamp(26px, 3vw, 38px);
  letter-spacing: -0.02em;
  margin: 12px 0;
}
.newsletter-card p { color: var(--text-muted); margin: 0; max-width: 50ch; }
.newsletter-form {
  display: flex;
  gap: 8px;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 6px;
}
.newsletter-form input {
  flex: 1;
  background: none;
  border: 0;
  outline: 0;
  color: var(--text);
  padding: 12px 18px;
  font-size: 15px;
  min-width: 0;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-note { color: var(--text-dim); font-size: 12.5px; margin-top: 12px; }
.newsletter-status { font-size: 14px; margin-top: 10px; min-height: 20px; }
.newsletter-status[data-state="ok"] { color: var(--ok); }
.newsletter-status[data-state="err"] { color: var(--danger); }

/* ---------- Footer ---------- */
.site-footer {
  background: #07090b;
  color: var(--text-muted);
  padding: 64px 0 28px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer-brand .brand { color: var(--text); margin-bottom: 16px; }
.footer-brand p { font-size: 14px; max-width: 36ch; margin: 0 0 18px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text-muted);
  transition: color .15s, border-color .15s, background .15s;
}
.socials a:hover { color: var(--accent); border-color: var(--accent); background: var(--bg-elev); }
.socials svg { width: 16px; height: 16px; }

.footer-col h4 {
  color: var(--text);
  font-size: 13.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin: 0 0 16px;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { color: var(--text-muted); font-size: 14px; }
.footer-col a:hover { color: var(--text); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border);
  padding-top: 24px;
  font-size: 13px;
  flex-wrap: wrap;
  gap: 16px;
}
.payments { display: flex; gap: 8px; align-items: center; }
.pay-chip {
  padding: 4px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  bottom: 24px;
  right: 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 200;
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  animation: toastIn .25s ease-out;
}
.toast .check {
  width: 22px; height: 22px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  display: grid; place-items: center;
  font-weight: 900;
  font-size: 13px;
}
@keyframes toastIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------- Visually-hidden / a11y ---------- */
.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px) {
  .hero-inner { grid-template-columns: 1fr; gap: 36px; padding: 56px 0 64px; }
  .hero-visual { aspect-ratio: 16/10; max-width: 640px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card.featured { grid-row: auto; grid-column: span 2; min-height: 240px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.feature { grid-row: auto; grid-column: span 2; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .promo-grid { grid-template-columns: 1fr 1fr; }
  .search { width: 200px; }
  .newsletter-card { grid-template-columns: 1fr; padding: 36px; }
}

@media (max-width: 720px) {
  .container { padding: 0 16px; }
  .topbar-links { display: none; }
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: auto 1fr auto; height: 64px; }
  .search { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.featured { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.feature { grid-column: auto; }
  .promo-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .section { padding: 56px 0; }
  .section-header { flex-direction: column; align-items: flex-start; }
  .newsletter-form { flex-direction: column; border-radius: 16px; }
  .newsletter-form .btn { width: 100%; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .product-emoji { font-size: 72px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
  html { scroll-behavior: auto; }
}
