:root {
  --bg: #0b0d10;
  --bg-elev: #14171c;
  --bg-elev-2: #1b1f26;
  --border: #262b34;
  --border-strong: #3a4150;
  --text: #f2f3f5;
  --text-muted: #9aa3b2;
  --text-dim: #6b7280;
  --accent: #d4ff3a;
  --accent-ink: #0b0d10;
  --danger: #ff5470;
  --warn: #ffb547;
  --ok: #4ade80;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);
  --focus: 0 0 0 3px rgba(212, 255, 58, 0.55);
  --maxw: 1240px;
  --font-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Inter", var(--font-sans);
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-sans);
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

button { font: inherit; cursor: pointer; border: 0; background: none; color: inherit; }

:focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: 6px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  font-weight: 700;
  z-index: 1000;
  border-radius: 0 0 8px 0;
}
.skip-link:focus { left: 0; }

.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* ---------- Top bar / Header ---------- */
.topbar {
  background: #000;
  color: var(--text-muted);
  font-size: 13px;
  border-bottom: 1px solid var(--border);
}
.topbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 36px;
  gap: 16px;
}
.topbar-msg { font-weight: 500; color: #d6d8de; }
.topbar-msg strong { color: var(--accent); }
.topbar-links { display: flex; gap: 18px; }
.topbar-links a:hover { color: var(--text); }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: saturate(140%) blur(12px);
  -webkit-backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  height: 72px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: 22px;
  letter-spacing: -0.02em;
}
.brand-mark {
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  font-weight: 900;
}
.primary-nav ul {
  display: flex;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
  justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 999px;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 14.5px;
  transition: color .15s, background .15s;
}
.primary-nav a:hover,
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  position: relative;
  width: 40px;
  height: 40px;
  display: inline-grid;
  place-items: center;
  border-radius: 10px;
  color: var(--text-muted);
  transition: background .15s, color .15s;
}
.icon-btn:hover { background: var(--bg-elev); color: var(--text); }
.icon-btn svg { width: 20px; height: 20px; }
.badge {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 11px;
  font-weight: 800;
  display: grid;
  place-items: center;
}

.search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 8px 14px;
  width: 280px;
  transition: border-color .15s, background .15s;
}
.search:focus-within { border-color: var(--border-strong); background: var(--bg-elev-2); }
.search svg { width: 16px; height: 16px; color: var(--text-muted); flex: none; }
.search input {
  background: none;
  border: 0;
  outline: 0;
  color: var(--text);
  font-size: 14px;
  width: 100%;
}
.search input::placeholder { color: var(--text-dim); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14.5px;
  letter-spacing: 0.01em;
  transition: transform .08s, background .15s, color .15s, border-color .15s;
  border: 1px solid transparent;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: #e0ff66; }
.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-elev); }
.btn-ghost { color: var(--text-muted); padding: 10px 14px; }
.btn-ghost:hover { color: var(--text); background: var(--bg-elev); }
.btn-link {
  color: var(--accent);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-link:hover { text-decoration: underline; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid var(--border);
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(900px 500px at 80% 10%, rgba(212,255,58,0.10), transparent 60%),
    radial-gradient(700px 400px at 10% 90%, rgba(96, 165, 250, 0.08), transparent 60%);
  pointer-events: none;
}
.hero-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 56px;
  align-items: center;
  padding: 80px 0 96px;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.eyebrow .dot {
  width: 6px; height: 6px; border-radius: 999px;
  background: var(--accent);
  box-shadow: 0 0 10px var(--accent);
}
.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(40px, 6vw, 72px);
  line-height: 1.02;
  letter-spacing: -0.03em;
  margin: 18px 0 18px;
  font-weight: 800;
}
.hero h1 em {
  font-style: normal;
  background: linear-gradient(90deg, var(--accent), #6ee7b7);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p.lead {
  color: var(--text-muted);
  font-size: 18px;
  max-width: 50ch;
  margin: 0 0 28px;
}
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.hero-meta {
  display: flex;
  align-items: center;
  gap: 24px;
  margin-top: 36px;
  flex-wrap: wrap;
}
.hero-meta .stat strong {
  display: block;
  font-size: 22px;
  font-family: var(--font-display);
  letter-spacing: -0.01em;
}
.hero-meta .stat span {
  color: var(--text-dim);
  font-size: 13px;
}
.hero-divider { width: 1px; height: 32px; background: var(--border); }

.hero-visual {
  position: relative;
  aspect-ratio: 4/5;
  background:
    radial-gradient(circle at 30% 20%, rgba(212,255,58,0.18), transparent 55%),
    linear-gradient(160deg, #1d2128, #0e1014);
  border: 1px solid var(--border);
  border-radius: 24px;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.hero-visual .product-card-floating {
  position: absolute;
  background: rgba(20, 23, 28, 0.85);
  backdrop-filter: blur(8px);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}
.hero-visual .pcf-1 { top: 24px; left: 24px; }
.hero-visual .pcf-2 { bottom: 24px; right: 24px; }
.hero-visual .pcf-thumb {
  width: 44px; height: 44px;
  border-radius: 8px;
  background: linear-gradient(135deg, #2a2f38, #1a1d22);
  display: grid; place-items: center;
  font-size: 22px;
}
.hero-visual .pcf-info small { color: var(--text-dim); display: block; font-size: 11.5px; }
.hero-visual .pcf-info strong { font-size: 13px; }
.hero-visual .product-hero-img {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: clamp(160px, 28vw, 320px);
  filter: drop-shadow(0 30px 40px rgba(0,0,0,0.55));
}

/* ---------- Section header ---------- */
.section { padding: 72px 0; border-bottom: 1px solid var(--border); }
.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 32px;
}
.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 3.4vw, 40px);
  letter-spacing: -0.02em;
  margin: 8px 0 6px;
  font-weight: 800;
}
.section-header p {
  color: var(--text-muted);
  margin: 0;
  max-width: 56ch;
}
.section-eyebrow {
  font-size: 12.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 700;
}

/* ---------- Category strip ---------- */
.category-strip { padding: 36px 0; border-bottom: 1px solid var(--border); }
.category-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 12px;
}
.category-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 16px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  transition: transform .15s, border-color .15s, background .15s;
}
.category-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-strong);
  background: var(--bg-elev-2);
}
.category-icon {
  width: 44px; height: 44px;
  display: grid; place-items: center;
  border-radius: 12px;
  background: var(--bg-elev-2);
  font-size: 22px;
}
.category-card span { font-weight: 600; font-size: 14px; }
.category-card small { color: var(--text-dim); font-size: 12px; }

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .18s, border-color .18s, box-shadow .18s;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
  box-shadow: 0 18px 40px rgba(0,0,0,0.45);
}
.product-media {
  position: relative;
  aspect-ratio: 1 / 1;
  background:
    radial-gradient(circle at 50% 30%, rgba(255,255,255,0.05), transparent 60%),
    linear-gradient(160deg, #1f242c, #11141a);
  display: grid;
  place-items: center;
  overflow: hidden;
}
.product-emoji {
  font-size: 96px;
  filter: drop-shadow(0 12px 20px rgba(0,0,0,0.5));
  transition: transform .3s;
}
.product-card:hover .product-emoji { transform: scale(1.06); }
.product-tag {
  position: absolute;
  top: 12px; left: 12px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  background: var(--accent);
  color: var(--accent-ink);
}
.product-tag.new { background: #6ee7b7; }
.product-tag.sale { background: var(--danger); color: #fff; }
.product-tag.limited { background: var(--warn); color: #1a1404; }
.wishlist-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 36px; height: 36px;
  display: grid; place-items: center;
  background: rgba(0,0,0,0.45);
  border-radius: 999px;
  color: #fff;
  border: 1px solid rgba(255,255,255,0.08);
  transition: background .15s, color .15s;
}
.wishlist-btn:hover { background: rgba(0,0,0,0.7); color: var(--accent); }
.wishlist-btn[aria-pressed="true"] { color: var(--danger); }
.wishlist-btn svg { width: 18px; height: 18px; }

.product-body { padding: 16px; display: flex; flex-direction: column; gap: 8px; }
.product-meta { display: flex; justify-content: space-between; align-items: baseline; }
.product-cat { color: var(--text-dim); font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; }
.product-rating { display: inline-flex; align-items: center; gap: 4px; font-size: 12.5px; color: var(--text-muted); }
.product-rating svg { width: 14px; height: 14px; color: var(--warn); }
.product-name { font-size: 15.5px; font-weight: 600; margin: 0; }
.product-price-row { display: flex; align-items: center; justify-content: space-between; margin-top: 4px; }
.product-price { font-family: var(--font-display); font-size: 18px; font-weight: 700; }
.product-price .was { color: var(--text-dim); text-decoration: line-through; font-weight: 500; font-size: 14px; margin-left: 8px; }
.add-cart-btn {
  width: 36px; height: 36px;
  border-radius: 10px;
  background: var(--bg-elev-2);
  display: grid; place-items: center;
  color: var(--text);
  transition: background .15s, color .15s;
  border: 1px solid var(--border);
}
.add-cart-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.add-cart-btn svg { width: 16px; height: 16px; }

/* ---------- Tabs / filters ---------- */
.filters { display: flex; gap: 8px; flex-wrap: wrap; }
.chip {
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 13.5px;
  font-weight: 500;
  transition: all .15s;
}
.chip:hover { color: var(--text); border-color: var(--border-strong); }
.chip[aria-pressed="true"] {
  background: var(--text);
  color: var(--accent-ink);
  border-color: var(--text);
}

/* ---------- Deals section ---------- */
.deals { background: var(--bg-elev); }
.deals-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  gap: 20px;
}
.deal-card {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  padding: 32px;
  border: 1px solid var(--border);
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: transform .18s;
}
.deal-card:hover { transform: translateY(-3px); }
.deal-card.featured {
  grid-row: span 2;
  background: linear-gradient(160deg, #16331c 0%, #0e1c12 60%, #0b0d10 100%);
  border-color: #1f4128;
}
.deal-card.b {
  background: linear-gradient(160deg, #2a1633 0%, #14091a 100%);
  border-color: #3a1f48;
}
.deal-card.c {
  background: linear-gradient(160deg, #331b16 0%, #1a0c09 100%);
  border-color: #5a2c20;
}
.deal-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255,255,255,0.08);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.deal-card h3 {
  font-family: var(--font-display);
  font-size: clamp(24px, 2.4vw, 36px);
  letter-spacing: -0.02em;
  margin: 16px 0 8px;
  max-width: 14ch;
  line-height: 1.05;
}
.deal-card p { color: rgba(255,255,255,0.7); margin: 0 0 16px; max-width: 32ch; }
.deal-card .deal-emoji {
  position: absolute;
  right: -10px;
  bottom: -20px;
  font-size: 180px;
  opacity: 0.3;
  line-height: 1;
  pointer-events: none;
}
.deal-card.featured .deal-emoji { font-size: 240px; right: -20px; bottom: -30px; opacity: 0.4; }

.countdown {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.countdown-block {
  background: rgba(0,0,0,0.4);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  padding: 6px 10px;
  text-align: center;
  min-width: 48px;
}
.countdown-block strong {
  display: block;
  font-family: var(--font-display);
  font-size: 18px;
  font-variant-numeric: tabular-nums;
}
.countdown-block span { font-size: 10px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.08em; }

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}
.editorial-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .18s, border-color .18s;
}
.editorial-card:hover { transform: translateY(-3px); border-color: var(--border-strong); }
.editorial-card.feature { grid-row: span 2; }
.editorial-media {
  aspect-ratio: 16/10;
  position: relative;
  display: grid;
  place-items: center;
  font-size: 96px;
  overflow: hidden;
}
.editorial-card.feature .editorial-media { aspect-ratio: 5/4; font-size: 140px; }
.em-1 { background: linear-gradient(160deg, #1c2740, #0a0f1c); }
.em-2 { background: linear-gradient(160deg, #2a1f12, #160d05); }
.em-3 { background: linear-gradient(160deg, #122a26, #061513); }
.em-4 { background: linear-gradient(160deg, #2c1326, #150612); }
.em-5 { background: linear-gradient(160deg, #1f2030, #0c0d15); }

.editorial-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  font-size: 11.5px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 700;
}
.editorial-body h3 {
  font-family: var(--font-display);
  font-size: 20px;
  letter-spacing: -0.01em;
  margin: 8px 0 8px;
  line-height: 1.25;
}
.editorial-card.feature h3 { font-size: 28px; }
.editorial-body p { color: var(--text-muted); margin: 0 0 16px; font-size: 14.5px; }
.editorial-meta {
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-dim);
  font-size: 12.5px;
}
.author-dot {
  width: 26px; height: 26px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--accent), #6ee7b7);
  display: grid; place-items: center;
  color: var(--accent-ink);
  font-weight: 800;
  font-size: 11px;
}

/* ---------- Banner / promo strip ---------- */
.promo-strip {
  background: var(--bg-elev);
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}
.promo-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  padding: 28px 0;
}
.promo-item {
  display: flex;
  align-items: center;
  gap: 14px;
}
.promo-icon {
  width: 44px; height: 44px;
  display: grid; place-items: center;
  background: var(--bg-elev-2);
  border: 1px solid var(--border);
  border-radius: 12px;
  color: var(--accent);
}
.promo-icon svg { width: 22px; height: 22px; }
.promo-item strong { display: block; font-size: 14px; }
.promo-item span { color: var(--text-dim); font-size: 12.5px; }

/* ---------- Newsletter ---------- */
.newsletter {
  padding: 72px 0;
  border-bottom: 1px solid var(--border);
}
.newsletter-card {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(700px 300px at 80% 20%, rgba(212,255,58,0.12), transparent 60%),
    linear-gradient(160deg, #161a20, #0e1115);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 56px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  align-items: center;
}
.newsletter-card h2 {
  font-family: var(--font-display);
  font-size: clamp(26px, 3vw, 38px);
  letter-spacing: -0.02em;
  margin: 12px 0;
}
.newsletter-card p { color: var(--text-muted); margin: 0; max-width: 50ch; }
.newsletter-form {
  display: flex;
  gap: 8px;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 6px;
}
.newsletter-form input {
  flex: 1;
  background: none;
  border: 0;
  outline: 0;
  color: var(--text);
  padding: 12px 18px;
  font-size: 15px;
  min-width: 0;
}
.newsletter-form input::placeholder { color: var(--text-dim); }
.newsletter-note { color: var(--text-dim); font-size: 12.5px; margin-top: 12px; }
.newsletter-status { font-size: 14px; margin-top: 10px; min-height: 20px; }
.newsletter-status[data-state="ok"] { color: var(--ok); }
.newsletter-status[data-state="err"] { color: var(--danger); }

/* ---------- Footer ---------- */
.site-footer {
  background: #07090b;
  color: var(--text-muted);
  padding: 64px 0 28px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer-brand .brand { color: var(--text); margin-bottom: 16px; }
.footer-brand p { font-size: 14px; max-width: 36ch; margin: 0 0 18px; }
.socials { display: flex; gap: 8px; }
.socials a {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text-muted);
  transition: color .15s, border-color .15s, background .15s;
}
.socials a:hover { color: var(--accent); border-color: var(--accent); background: var(--bg-elev); }
.socials svg { width: 16px; height: 16px; }

.footer-col h4 {
  color: var(--text);
  font-size: 13.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin: 0 0 16px;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { color: var(--text-muted); font-size: 14px; }
.footer-col a:hover { color: var(--text); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--border);
  padding-top: 24px;
  font-size: 13px;
  flex-wrap: wrap;
  gap: 16px;
}
.payments { display: flex; gap: 8px; align-items: center; }
.pay-chip {
  padding: 4px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  bottom: 24px;
  right: 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 200;
  pointer-events: none;
}
.toast {
  pointer-events: auto;
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  animation: toastIn .25s ease-out;
}
.toast .check {
  width: 22px; height: 22px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  display: grid; place-items: center;
  font-weight: 900;
  font-size: 13px;
}
@keyframes toastIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------- Visually-hidden / a11y ---------- */
.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px) {
  .hero-inner { grid-template-columns: 1fr; gap: 36px; padding: 56px 0 64px; }
  .hero-visual { aspect-ratio: 16/10; max-width: 640px; }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .category-grid { grid-template-columns: repeat(3, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card.featured { grid-row: auto; grid-column: span 2; min-height: 240px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.feature { grid-row: auto; grid-column: span 2; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .promo-grid { grid-template-columns: 1fr 1fr; }
  .search { width: 200px; }
  .newsletter-card { grid-template-columns: 1fr; padding: 36px; }
}

@media (max-width: 720px) {
  .container { padding: 0 16px; }
  .topbar-links { display: none; }
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: auto 1fr auto; height: 64px; }
  .search { display: none; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .category-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card.featured { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.feature { grid-column: auto; }
  .promo-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .section { padding: 56px 0; }
  .section-header { flex-direction: column; align-items: flex-start; }
  .newsletter-form { flex-direction: column; border-radius: 16px; }
  .newsletter-form .btn { width: 100%; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .product-emoji { font-size: 72px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
  html { scroll-behavior: auto; }
}

