+  line-height: 1.05;
+}
+.deal-card p { color: rgba(255,255,255,0.7); margin: 0 0 16px; max-width: 32ch; }
+.deal-card .deal-emoji {
+  position: absolute;
+  right: -10px;
+  bottom: -20px;
+  font-size: 180px;
+  opacity: 0.3;
+  line-height: 1;
+  pointer-events: none;
+}
+.deal-card.featured .deal-emoji { font-size: 240px; right: -20px; bottom: -30px; opacity: 0.4; }
+
+.countdown {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  margin-top: 8px;
+}
+.countdown-block {
+  background: rgba(0,0,0,0.4);
