+.promo-icon svg { width: 22px; height: 22px; }
+.promo-item strong { display: block; font-size: 14px; }
+.promo-item span { color: var(--text-dim); font-size: 12.5px; }
+
+/* ---------- Newsletter ---------- */
+.newsletter {
+  padding: 72px 0;
+  border-bottom: 1px solid var(--border);
+}
+.newsletter-card {
+  position: relative;
+  overflow: hidden;
+  background:
