function Newsletter() {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState({ state: "", msg: "" });

  const submit = (e) => {
    e.preventDefault();
    const ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!ok) {
      setStatus({ state: "err", msg: "Please enter a valid email address." });
