function Footer() {
  const cols = [
    { title: "Shop", links: ["New arrivals", "Best sellers", "Sale", "Gift cards", "Lookbook"] },
    { title: "Help", links: ["Contact us", "Shipping & returns", "Size guide", "Order tracking", "FAQ"] },
