            h("a", { href: "#youtube", "aria-label": "YouTube" }, Icon.yt()),
            h("a", { href: "#pinterest", "aria-label": "Pinterest" }, Icon.pin())
          )
        ),
        cols.map((col) =>
          h("div", { className: "footer-col", key: col.title },
            h("h4", null, col.title),
            h("ul", null,
              col.links.map((l) => h("li", { key: l }, h("a", { href: `#${l.toLowerCase().replace(/\s+/g, "-")}` }, l)))
            )
          )
        )
      ),
      h("div", { className: "footer-bottom" },
        h("span", null, "© ", new Date().getFullYear(), " Lumen Goods Co. — All rights reserved."),
        h("div", { className: "payments", "aria-label": "Accepted payment methods" },
          ["VISA", "MC", "AMEX", "PAYPAL", "APPLE", "GPAY"].map((p) =>
            h("span", { key: p, className: "pay-chip" }, p)
          )
        )
      )
    )
  );
}

/* -------------------- App -------------------- */
function App() {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const pushToast = React.useContext(ToastContext);

  const addToCart = useCallback((product) => {
    setCart((c) => [...c, product.id]);
    pushToast(`Added "${product.name}" to cart`);
  }, [pushToast]);

  const toggleWish = useCallback((product) => {
    setWishlist((s) => {
      const next = new Set(s);
      if (next.has(product.id)) {
        next.delete(product.id);
        pushToast(`Removed "${product.name}" from wishlist`);
      } else {
        next.add(product.id);
        pushToast(`Saved "${product.name}" to wishlist`);
      }
      return next;
    });
  }, [pushToast]);

  return h(Fragment, null,
    h("a", { href: "#main", className: "skip-link" }, "Skip to main content"),
    h(TopBar, null),
    h(Header, { cartCount: cart.length, wishCount: wishlist.size }),
    h("main", { id: "main" },
      h(Hero, null),
      h(CategoryStrip, null),
      h(FeaturedProducts, { onAdd: addToCart, onWish: toggleWish, wishlist }),
      h(Deals, null),
      h(Editorial, null),
      h(PromoStrip, null),
      h(Newsletter, null)
    ),
    h(Footer, null)
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(h(ToastProvider, null, h(App, null)));
