/* -------------------- Toast context (simple) -------------------- */
const ToastContext = React.createContext(() => {});

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);
  const idRef = useRef(0);

  const push = useCallback((message) => {
    const id = ++idRef.current;
    setToasts((t) => [...t, { id, message }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 2800);
  }, []);

  return h(ToastContext.Provider, { value: push },
    children,
    h("div", { className: "toast-region", role: "status", "aria-live": "polite", "aria-atomic": "true" },
      toasts.map((t) =>
        h("div", { key: t.id, className: "toast" },
          h("span", { className: "check", "aria-hidden": "true" }, "✓"),
          h("span", null, t.message)
        )
      )
    )
  );
}

