function Countdown() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 26 + 1000 * 60 * 47, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, target - now);
  const h_ = Math.floor(diff / 3.6e6);
  const m = Math.floor((diff % 3.6e6) / 6e4);
  const s = Math.floor((diff % 6e4) / 1000);
  const pad = (n) => String(n).padStart(2, "0");

  return h("div", { className: "countdown", "aria-label": `Sale ends in ${h_} hours, ${m} minutes, ${s} seconds` },
    [["Hrs", h_], ["Min", m], ["Sec", s]].map(([label, val]) =>
      h("div", { key: label, className: "countdown-block", "aria-hidden": "true" },
        h("strong", null, pad(val)),
        h("span", null, label)
      )
    )
  );
}

